insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$f213edc8-ce9f-5478-aaf8-bff542a0c695$mm$, 374, $mm$Pediatrics$mm$, $mm$Cerebral palsy$mm$, $mm$Non-progressive brain injury affecting movement and posture. Signs: persistent primitive reflexes, abnormal tone, delays. Safety, nutrition, mobility, seizure care.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$79ec74b5-72ae-5919-8b01-f314d50e7adb$mm$, 375, $mm$Pediatrics$mm$, $mm$Autism spectrum disorder$mm$, $mm$Difficulty with social communication, repetitive behaviors, strict routines, sensory sensitivity. Keep routines consistent, minimize stimulation, prepare for changes.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$07cdac86-8770-5913-bda1-63fc8e389ace$mm$, 376, $mm$Pediatrics$mm$, $mm$ADHD$mm$, $mm$Inattention, hyperactivity, impulsivity. Stimulants given in the morning; watch appetite, sleep and growth. Structured routine, a set study area, short tasks.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$fa75db1a-d1d8-5960-bfc2-0d3db1c38fdd$mm$, 377, $mm$Pediatrics$mm$, $mm$Juvenile idiopathic arthritis$mm$, $mm$Joint stiffness worse in the morning. NSAIDs given around the clock, warm baths, ROM exercise, regular eye exams (uveitis).$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$9691eefe-9a00-57a8-b2d6-4e1539c13713$mm$, 378, $mm$Pediatrics$mm$, $mm$Appendicitis$mm$, $mm$Periumbilical pain moving to right lower quadrant (McBurney point), fever, vomiting. Sudden pain relief = perforation. No heat, laxatives or enemas.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$8f3e711e-b644-5c7e-a985-f1a467f00613$mm$, 379, $mm$Pediatrics$mm$, $mm$Celiac disease$mm$, $mm$Gluten damages the intestine. Avoid BROW: barley, rye, oats (unless certified gluten-free), wheat. Rice and corn are safe.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$0798e558-9a00-5a71-ab75-e4ddf72412b1$mm$, 380, $mm$Pediatrics$mm$, $mm$Gastroenteritis in children$mm$, $mm$Oral rehydration solution in small, frequent amounts; resume normal diet early. Avoid juice, soda, sports drinks and the BRAT diet as the only foods.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$edd8da43-e7a0-583a-b8a8-25adec127eee$mm$, 381, $mm$Pediatrics$mm$, $mm$Constipation and encopresis$mm$, $mm$Fiber, fluids, regular toilet sitting after meals, stool softeners. Encopresis = soiling from chronic constipation; avoid punishment.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$21bf7aa8-b447-52af-99cf-04ccee6e1091$mm$, 382, $mm$Pediatrics$mm$, $mm$Vesicoureteral reflux$mm$, $mm$Urine flows back up toward the kidneys → repeated UTIs and kidney damage. Frequent voiding, prophylactic antibiotics, sometimes surgery.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$d77fbe5b-2a89-5136-a5d7-f784775c47b8$mm$, 383, $mm$Pediatrics$mm$, $mm$UTI prevention in children$mm$, $mm$Void often and fully, wipe front to back, avoid bubble baths, cotton underwear, treat constipation, adequate fluids.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$b2dfcd8d-4d1d-5f09-adec-d0c71afcac97$mm$, 384, $mm$Pediatrics$mm$, $mm$Enuresis$mm$, $mm$Bedwetting after age 5. Limit fluids before bed, void before sleep, bedwetting alarms, desmopressin. Never punish.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$969b3889-7577-59ab-b848-a1addd96667a$mm$, 385, $mm$Pediatrics$mm$, $mm$Type 1 diabetes: hypoglycemia$mm$, $mm$Shaky, sweaty, irritable, pale. Rule of 15: 15 g fast carbs, recheck in 15 minutes. Unconscious → glucagon. Teach school staff.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$2ce9d18a-4531-5022-85fc-e53a3fa050f1$mm$, 386, $mm$Pediatrics$mm$, $mm$Type 1 diabetes: sick days$mm$, $mm$Keep giving insulin, check glucose every 2–4 hours and ketones, push sugar-free fluids. Call for vomiting, ketones or glucose >240.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$7b5531bb-80a6-5b3e-a313-19044d4a252f$mm$, 387, $mm$Pediatrics$mm$, $mm$DKA in children$mm$, $mm$Hyperglycemia, ketones, acidosis, Kussmaul breathing, fruity breath. Fluids and insulin given slowly — watch for CEREBRAL EDEMA (headache, change in LOC).$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$24413a78-8522-540b-9cf6-3b4f0edb4de5$mm$, 388, $mm$Pediatrics$mm$, $mm$Leukemia (ALL)$mm$, $mm$Most common childhood cancer. Bone marrow crowding → anemia (fatigue), low platelets (bruising, bleeding), low WBCs (infection). Neutropenic precautions; no rectal temps.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$f39e712a-ec5c-5ed9-8dc4-c803c02cad4a$mm$, 389, $mm$Pediatrics$mm$, $mm$Neutropenic precautions$mm$, $mm$Private room, strict handwashing, no fresh flowers or raw fruits/vegetables, no live vaccines, avoid sick visitors, no rectal temps or meds.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$1e95e1fc-7563-50ef-a499-70b595897c3a$mm$, 390, $mm$Pediatrics$mm$, $mm$Brain tumor signs$mm$, $mm$Morning headache and vomiting, unsteady gait, behavior changes, vision changes, head tilt. Most common solid tumor in children.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$3265d760-044b-5a95-81fa-843868946845$mm$, 391, $mm$Pediatrics$mm$, $mm$Seizure care$mm$, $mm$Protect from injury, side-lying, nothing in the mouth, time the seizure, suction and O2 ready. >5 minutes = status epilepticus → rescue benzodiazepine.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$c56e7ade-a6d5-5c45-a6a8-f209166de88a$mm$, 392, $mm$Pediatrics$mm$, $mm$Head injury in children$mm$, $mm$Watch LOC, vomiting, pupils, irritability, headache. Infants: bulging fontanel, high-pitched cry. Late ICP signs: Cushing triad (high BP, low HR, irregular breathing).$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$7941a919-39fa-5119-954b-06a851bc3ec8$mm$, 393, $mm$Pediatrics$mm$, $mm$Abusive head trauma (shaken baby)$mm$, $mm$Retinal hemorrhages, subdural bleeding, lethargy, seizures, vomiting without a clear injury story. Report suspicion; teach parents coping for crying.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$81c0923c-411b-513e-9895-85f2c4ff122c$mm$, 394, $mm$Pediatrics$mm$, $mm$Fabricated illness by a caregiver$mm$, $mm$Caregiver causes or invents symptoms for attention (formerly Munchausen by proxy). Clue: symptoms only occur when that caregiver is present.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$dbb8e78d-0c5f-5ffb-842a-eca44e4f3786$mm$, 395, $mm$Pediatrics$mm$, $mm$Foreign body aspiration$mm$, $mm$Sudden coughing, choking, wheezing on one side. Choking infant: 5 back blows + 5 chest thrusts · child: abdominal thrusts. No blind finger sweeps.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$f45b486d-5a4a-50ae-9beb-172787c225c6$mm$, 396, $mm$Pediatrics$mm$, $mm$Pediatric CPR$mm$, $mm$Rate 100–120/min · Depth: 1/3 of chest (about 1.5 in infant, 2 in child) · 30:2 one rescuer, 15:2 two rescuers · infant pulse check at brachial artery.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$4daa2a8e-baa1-5231-8c15-32088bb6b2a2$mm$, 397, $mm$Pediatrics$mm$, $mm$Pneumonia in children$mm$, $mm$Fever, cough, tachypnea, retractions, crackles. Position upright, O2, fluids, antibiotics if bacterial; watch SpO2 and work of breathing.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$cccbf221-5807-5e73-9338-f62f47819ca7$mm$, 398, $mm$Pediatrics$mm$, $mm$Signs of respiratory distress (child)$mm$, $mm$Nasal flaring, retractions, grunting, head bobbing, tachypnea, restlessness, then lethargy. Cyanosis is LATE.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$caee14af-447a-56e9-87d8-c785bb5b08a2$mm$, 399, $mm$Pediatrics$mm$, $mm$Immune thrombocytopenia (ITP)$mm$, $mm$Low platelets after a viral illness: petechiae, bruising, nosebleeds. Avoid contact sports, aspirin and NSAIDs; soft toothbrush.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$6d9a3688-7acd-5bb0-9b1b-dc3077760ee8$mm$, 400, $mm$Pediatrics$mm$, $mm$Coarctation of the aorta$mm$, $mm$Narrowed aorta: high BP and strong pulses in the ARMS, weak or absent femoral pulses and low BP in the legs.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$006abf49-24e5-5cc0-83dd-7014ffd9d9dc$mm$, 401, $mm$Pediatrics$mm$, $mm$Patent ductus arteriosus$mm$, $mm$Ductus stays open (common in preemies): machine-like murmur, bounding pulses, wide pulse pressure. Indomethacin or ibuprofen may close it.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$06823c1b-72c9-5aaa-a800-2d875666e3fe$mm$, 402, $mm$Pediatrics$mm$, $mm$Cardiac catheterization care (child)$mm$, $mm$Keep the leg straight 4–8 hours, check pulses below the site, color and temperature of the leg, site bleeding, and fluid intake. Hold direct pressure if bleeding.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$c2166a1b-2c0f-53c2-b9bc-091400535e9b$mm$, 403, $mm$Pediatrics$mm$, $mm$Pediatric maintenance fluids$mm$, $mm$Holliday-Segar: 100 mL/kg/day for the first 10 kg + 50 mL/kg for the next 10 kg + 20 mL/kg for each kg above 20.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$d257e5c7-e58e-534c-acd7-988026c370ab$mm$, 404, $mm$Pediatrics$mm$, $mm$Pediatric urine output$mm$, $mm$Infants: about 1–2 mL/kg/hr · children: about 0.5–1 mL/kg/hr. 1 g of diaper weight = 1 mL urine.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$07f1fea8-daa1-5bf2-b673-4d5be9baac14$mm$, 405, $mm$Pediatrics$mm$, $mm$Giving oral meds to children$mm$, $mm$Use an oral syringe aimed at the inside of the cheek, small amounts; never mix in a whole bottle or essential foods; never call medicine candy.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$3dcc172b-13f3-5457-a7a1-2aeca5a9e0a6$mm$, 406, $mm$Pediatrics$mm$, $mm$IM injection sites (children)$mm$, $mm$Infants and young toddlers: vastus lateralis. Deltoid for older children (enough muscle mass). Avoid the dorsogluteal site in children.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$eee26551-3a99-5ed2-b360-c4561f199dfd$mm$, 407, $mm$Pediatrics$mm$, $mm$Ear drops by age$mm$, $mm$Under 3 years: pull pinna DOWN and back · 3 and older: pull UP and back.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$fc86072c-1aee-5343-a41b-a40d7881325c$mm$, 408, $mm$Pediatrics$mm$, $mm$Comfort for procedures$mm$, $mm$Infants: sucrose on a pacifier, swaddling, breastfeeding · Older children: topical numbing cream (EMLA about 60 minutes before), distraction, parent presence. Do painful procedures in a treatment room, not the bed.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$13aac94d-c4a3-5d1c-b037-548c52ceed60$mm$, 409, $mm$Pediatrics$mm$, $mm$Adolescent eating disorders$mm$, $mm$Anorexia: severe restriction, bradycardia, hypotension, amenorrhea, lanugo · Bulimia: binge/purge, dental erosion, low K. Watch for refeeding syndrome (low phosphorus) when feeding restarts.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$09e7431f-e3a5-549d-8f89-1e97337471ba$mm$, 410, $mm$Pediatrics$mm$, $mm$Adolescent depression and suicide risk$mm$, $mm$Ask directly about suicidal thoughts — it does not plant the idea. Warning signs: giving things away, withdrawal, talk of death. Remove means; never promise to keep it secret.$mm$, true) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$ddc9a958-a9f6-5fc5-ac61-bb5d7f09765f$mm$, 411, $mm$Pediatrics$mm$, $mm$Hip spica cast$mm$, $mm$Turn every 2 hours, keep cast edges padded and dry (protect from urine/stool), check circulation and skin, adapt car seat, never use the abduction bar to lift.$mm$, false) on conflict (id) do nothing;
insert into public.flashcard_library (id, card_number, topic, front, back, high_yield) values ($mm$fce8932e-bf3b-5103-ba36-03fd453dd585$mm$, 412, $mm$Pediatrics$mm$, $mm$Iron toxicity$mm$, $mm$Iron pills look like candy; ingestion can cause vomiting, GI bleeding and liver failure. Childproof caps; call Poison Control.$mm$, false) on conflict (id) do nothing;
